# src/tree_amplitudes.jl (generated) against FeynCalc values at fixed points
# (test/tree_amplitudes_reference.jl, generated by the same script).
using Test
include(joinpath(@__DIR__, "..", "src", "tree_amplitudes.jl"))
include(joinpath(@__DIR__, "tree_amplitudes_reference.jl"))
using .TreeAmplitudes

@testset "tree amplitudes vs FeynCalc" begin
    for r in TREE_REFERENCE
        proc = only(filter(q -> q.id == r.id, TREE_PROCESSES))
        val = r.id > 100 ? proc.msq(r.p) : proc.msq(r.s, r.t, r.p)
        @test isapprox(val, r.msq; rtol=1e-12)
        if proc.xyz !== nothing && r.id < 100
            # zero width: X/(s-m^2)^2 + 2Y/(s-m^2) + Z = msq
            m = proc.resonance === :A ? r.p.mA : r.p.mphi
            @test isapprox(msq_bw(proc.xyz(r.s, r.t, r.p), r.s, m, 0.0), r.msq; rtol=1e-10)
        end
    end
end
